const books = [
  { id: 17, title: "Moon", author: "Asha" },
  { id: 18, title: "Moon", author: "Ben" }
];
const copies = [
  { id: 203, bookId: 17, shelf: "B2" },
  { id: 204, bookId: 17, shelf: "B3" },
  { id: 205, bookId: 18, shelf: "C1" }
];
const book = books.find(item => item.id === 17);
const matchingCopies = copies.filter(copy => copy.bookId === 17);
console.log(book.title + " by " + book.author);
console.log("copies: " + matchingCopies.length);
console.log(matchingCopies.map(copy => copy.id + " on " + copy.shelf).join(", "));
